import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';

@Component({
  selector: 'order-history',
  templateUrl: './order-history.html',
  styleUrls: ['./order-history.scss'],
})
export class OrderHistoryPageComponent {
  constructor(
    public router: Router,
    private dxpService: DxpComponentService
  ) {}

  public innerHtml: string;

  async ionViewWillEnter() {
    await this.dxpService.onConnected();
    this.innerHtml = '<mag-order-container></mag-order-container>';
  }

  ionViewWillLeave() {
    this.innerHtml = '';
  }
}
