import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'order-rebuild',
  templateUrl: './order-rebuild.html',
  styleUrls: ['./order-rebuild.scss'],
})
export class OrderRebuildComponent {
  orderId = '';
  serviceId = '';

  constructor(
    public router: Router,
    private route: ActivatedRoute
  ) {}

  public dxpMagOrderRebuildContainer = '';

  ionViewWillEnter() {
    const params = this.route.snapshot.paramMap;
    this.orderId = params.get('orderId');
    this.serviceId = params.get('serviceId');
    this.dxpMagOrderRebuildContainer = `<mag-order-rebuild-container order-id=${this.orderId} service-id=${this.serviceId}></mag-order-rebuild-container>`;
  }

  ionViewDidLeave() {
    this.dxpMagOrderRebuildContainer = '';
  }
}
