import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { MagEComCoreApiHttpClient } from '@rsApp/modules/gateway/mag-ecom-core-api.service';
import { map } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class OrderService {
  constructor(
    private api: MagEComCoreApiHttpClient,
    private http: HttpClient
  ) {}

  getOrderById(id: string) {
    return this.api.get(`/order/v2.0/api/order/id/${id}/full`).pipe(
      map((data: any) => {
        return data;
      })
    );
  }
}
