import { Component, ElementRef, ViewChild } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'order-confirmation',
  templateUrl: './order-confirmation.html',
  styleUrls: ['./order-confirmation.scss'],
})
export class OrderConfirmationPageComponent {
  @ViewChild('buttonView') buttonView: ElementRef;
  public dxpMagOrderConfirmation = '';
  constructor(
    public router: Router,
    private route: ActivatedRoute
  ) {}

  ionViewWillEnter() {
    const params = this.route.snapshot.paramMap;
    const orderId = params.get('orderId');
    if (!orderId) {
      console.warn('orderId not found');
      return;
    }
    customElements.whenDefined('mag-order-confirmation').then(() => {
      this.dxpMagOrderConfirmation = `<mag-order-confirmation order-id=${orderId}></mag-order-confirmation>`;
    });
  }

  ionViewDidLeave() {
    this.dxpMagOrderConfirmation = '';
  }

  ionViewDidEnter() {
    this.handleHeightButtonView();
  }
  goHome() {
    this.router.navigate(['/tabs/home']);
  }

  handleHeightButtonView() {
    const content: HTMLElement = document.querySelector('.order-confirmation');
    const element: HTMLElement = this.buttonView.nativeElement;
    content.style.setProperty('--mag-order-confirmation-mb', `${element.offsetHeight}px`);
  }
}
