import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { OrderConfirmationPageComponent } from './pages/order-confirmation/order-confirmation';
import { OrderDetailPageComponent } from './pages/order-detail/order-detail.component';
import { OrderHistoryPageComponent } from './pages/order-history/order-history';
import { OrderModule } from './order.module';
import { OrderRebuildComponent } from './pages/order-rebuild/order-rebuild';

const routes: Routes = [
  {
    path: 'order-detail/:orderId',
    component: OrderDetailPageComponent,
    data: {
      hideTab: true,
      hiddenCartIcon: true,
    },
  },
  {
    path: 'order-rebuild/:orderId',
    component: OrderRebuildComponent,
    data: {
      hideTab: true,
      hiddenCartIcon: true,
    },
  },
  {
    path: 'order-history',
    component: OrderHistoryPageComponent,
    data: {
      hideTab: true,
      hiddenCartIcon: true,
    },
  },
  {
    path: 'order-confirmation/:orderId',
    component: OrderConfirmationPageComponent,
    data: {
      hideTab: true,
      hiddenCartIcon: true,
    },
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes), OrderModule],
  declarations: [],
})
export class OrderRoutingModule {}
