import { Component, HostListener, OnInit, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import { CacheService } from 'ionic-cache';
import { OrderService } from '../../providers/order.service';
import { firstValueFrom, Subject, takeUntil } from 'rxjs';
import {
  EDeliveryMethod,
  EOrderStatus,
  EPickingStatus,
  EPickupOrderMode,
  ErenderMethodMode,
  EUserPickupStatus,
} from '../../model/enum';
import { IPickupOrderMode } from '../../model/interface';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { Capacitor } from '@capacitor/core';

@Component({
  selector: 'order-detail',
  templateUrl: './order-detail.component.html',
  styleUrls: ['./order-detail.component.scss'],
})
export class OrderDetailPageComponent implements OnInit, OnDestroy {
  private _destroy$: Subject<boolean> = new Subject();
  private _initCompleted$ = new Subject<void>();
  orderId: string;
  orderNumber: string;
  curbsideLink: string;
  orderStatus: string;
  pickingOrderContent = EPickingStatus.Start;
  checkinContent = EPickingStatus.CheckIn;
  continuePickup = false;
  showPickingOrder: boolean;
  inStoreOption: boolean;
  curbSideOption = true;
  order: any;
  currentCurbsideOrderData: any;
  dxpOrderDetailReady = false;
  curbsideCheckReady = false;
  renderMethod: ErenderMethodMode = ErenderMethodMode.All;
  pickupData: IPickupOrderMode;
  actionType: string;

  constructor(
    public router: Router,
    private route: ActivatedRoute,
    public dxpComponentService: DxpComponentService,
    public utils: Utils,
    private cache: CacheService,
    private orderService: OrderService,
    public cre: Credential
  ) {}

  @HostListener('window:curbside:onMyWay', ['$event'])
  onMyWayHandler() {
    this.renderPickingMode();
  }

  ngOnInit() {
    this.route.params.pipe(takeUntil(this._destroy$)).subscribe((params) => {
      this.orderId = params?.orderId || '';
    });

    this.route.queryParams.pipe(takeUntil(this._destroy$)).subscribe((params) => {
      this.actionType = params?.action || '';
    });

    this._initCompleted$.pipe(takeUntil(this._destroy$)).subscribe(() => {
      if (Capacitor.isNativePlatform() && this.actionType) {
        this.openCubsideFromDeepLink(this.actionType);
      }
    });
  }

  ngOnDestroy() {
    this._destroy$.next(true);
    this._destroy$.complete();
  }

  async ionViewWillEnter() {
    try {
      await this.initOrderData();
      await this.initPickingData();
      await this.initCurbsideOrderData();
      this._initCompleted$.next();
    } catch (error) {
      console.error(error);
    }
  }

  async initPickingData() {
    this.pickupData = this.order?.Curbside;
    if (!this.pickupData) {
      console.error('No picking data found');
      return;
    }
  }

  checkOwnership(orderUserId: string): boolean {
    const currentUserId = this.cre?.currentUser?.UserId;

    if (!currentUserId || currentUserId != orderUserId) {
      this.router.navigateByUrl('/tabs/home');
      return false;
    }

    return true;
  }

  openCubsideFromDeepLink(action: string) {
    switch (action) {
      case 'pickup':
        this.postUserLocation();
        break;
      case 'checkin':
        this.walkInPickup();
        break;
    }
  }

  async initOrderData() {
    this.order = await this.fetchOrderDataById(this.orderId);
    if (!this.order) {
      console.error('Order not found');
      return;
    }

    const { OrderStatus, Curbside, OrderNumber, UserId } = this.order;
    if (Capacitor.isNativePlatform() && this.actionType) {
      const isOwner = this.checkOwnership(UserId);
      if (!isOwner) {
        return;
      }
    }
    this.orderStatus = OrderStatus;
    this.curbsideLink = Curbside?.CurbsideLink;
    this.orderNumber = OrderNumber;
    this.dxpOrderDetailReady = true;
  }

  async initCurbsideOrderData() {
    this.showPickingOrder = await this.checkShowPickingOrder();
    if (!this.showPickingOrder) return;
    this.changeAppCurbsideLink(this.curbsideLink);

    await this.renderPickingMode();
    this.curbsideCheckReady = true;
  }

  async fetchOrderDataById(id) {
    try {
      const orderData = await firstValueFrom(this.orderService.getOrderById(id));
      if (!orderData) return null;
      return orderData;
    } catch (error) {
      console.error('Error fetching order data:', error);
      return null;
    }
  }

  async fetchCacheCurbsideOrderData() {
    return await this.cache.getItem('curbside-order-data').catch(() => null);
  }

  async checkShowPickingOrder() {
    if (
      this.pickupData?.Geofence &&
      this.pickupData?.CurbsidePickup &&
      this.order?.DeliveryMethod === EDeliveryMethod.PICKUP
    ) {
      const currentOrderData = await this.fetchCacheCurbsideOrderData();
      let removedCacheData = false;
      if (currentOrderData) {
        const resolvedCacheOrderData = await this.fetchOrderDataById(currentOrderData?.orderId);
        if (resolvedCacheOrderData?.OrderStatus === EOrderStatus.Completed) {
          await this.cache.removeItem('curbside-order-data');
          removedCacheData = true;
        }

        if (removedCacheData) {
          return this.orderStatus === EOrderStatus.Ready || this.orderStatus === EOrderStatus.OutForPickedUp;
        }
        return String(currentOrderData?.orderId) === String(this.orderId);
      } else {
        return this.orderStatus === EOrderStatus.Ready || this.orderStatus === EOrderStatus.OutForPickedUp;
      }
    } else {
      return false;
    }
  }

  changeAppCurbsideLink(curbsideLink: string) {
    if (!curbsideLink) {
      return;
    }
    const url = new URL(curbsideLink);
    url.searchParams.set('inAppMode', 'true');

    this.curbsideLink = url.toString();
  }

  async renderPickingMode() {
    try {
      const pickupTypes = this.pickupData?.CurbsidePickupType || [];
      const hasInStore = pickupTypes.includes(EPickupOrderMode.IN_STORE);
      const hasCarryOut = pickupTypes.includes(EPickupOrderMode.CARRY_OUT);

      if (hasInStore && hasCarryOut) {
        if (this.isInStorePickupArrived() || (await this.isSameOrderPickup())) {
          this.renderMethod = ErenderMethodMode.Continue;
        } else {
          this.renderMethod = ErenderMethodMode.All;
        }
      } else if (hasInStore) {
        this.renderMethod = this.isInStorePickupArrived() ? ErenderMethodMode.Continue : ErenderMethodMode.CheckIn;
      } else if (hasCarryOut) {
        this.renderMethod = (await this.isSameOrderPickup()) ? ErenderMethodMode.Continue : ErenderMethodMode.Curbside;
      }
    } catch (err) {
      console.error('Error loading pickup mode', err);
    }
  }

  isInStorePickupArrived() {
    return this.order?.UserPickupStatus === EUserPickupStatus.Arrived;
  }

  async isSameOrderPickup() {
    const curbsideOrderData = await this.fetchCacheCurbsideOrderData();
    return curbsideOrderData && String(curbsideOrderData?.orderId) === String(this.orderId);
  }

  async handleClickContinuePickup() {
    if (this.isInStorePickupArrived()) {
      this.walkInPickup();
    }
    if (await this.isSameOrderPickup()) {
      this.postUserLocation();
    }
  }

  async walkInPickup() {
    const url = new URL(this.curbsideLink);
    url.searchParams.set('isWalkin', 'true');
    const curbsideLink = url.toString();

    this.dxpComponentService.listenToInAppBrowserEvents(curbsideLink, 'checkin', () => {
      this.renderPickingMode();
    });
  }

  async postUserLocation() {
    await this.dxpComponentService.checkPermissionLocation();
    this.dxpComponentService.listenToInAppBrowserEvents(this.curbsideLink, undefined, () => {
      this.renderPickingMode();
    });
  }
}
